      const fifthM = melActual-7;
      const halo = (fifthM>=40) ? [{ m:fifthM, v:Math.max(20,Math.round(melody.v*0.45)), durMs:noteDur, bass:false }] : [];
      accomp = [...anchor, ...halo].filter(n=>n.m!==melActual);
