  const langRef = useRef(lang);
  useEffect(()=>{ langRef.current = lang; }, [lang]);
  const [langOpen, setLangOpen] = useState(false);
  const t = useCallback((key) => I18N[lang]?.[key] ?? I18N.EN[key] ?? key, [lang]);

  // ─── Paintiano Pro state (from 07-pro.jsx) ───
