          ctx.fillStyle = `rgba(${rp.r},${rp.g},${rp.b},${(alpha*0.18).toFixed(3)})`;
          ctx.beginPath();
          ctx.arc(rp.x, rp.y, radius * 0.7, 0, Math.PI * 2);
          ctx.fill();
