      // the previous tick so the canvas doesn't freeze on the last-drawn frame.
      if (!playingRef.current) {
        if (canvas) {
          const ctx = canvas.getContext('2d');
          ctx.clearRect(0, 0, canvas.width, canvas.height);
        }
        cachedIdx = -1;
        highlightRunningRef.current = false;
        return;
      }
